/* ---------- Costruzione della firma (come quella in uso) ---------- */

function escapeHtml(t) {
  return String(t)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// src: { logo: "...", badge: "..." }
