/* ---------- Logica ---------- */

function log(m) { try { console.log("[Firme TS] " + m); } catch (e) {} }

// Si assicura che le immagini siano incorporate nella mail; restituisce gli indirizzi da usare
function preparaImmagini(item, poi) {
  var src = { logo: IMMAGINI.logo.url, badge: IMMAGINI.badge.url };
  item.getAttachmentsAsync(function (a) {
    if (a.status !== Office.AsyncResultStatus.Succeeded) { poi(src); return; }
    var presenti = {};
    for (var i = 0; i < a.value.length; i++) { presenti[a.value[i].name] = true; }
    var chiavi = ["logo", "badge"];
    var passo = function (k) {
      if (k >= chiavi.length) { poi(src); return; }
      var img = IMMAGINI[chiavi[k]];
      if (presenti[img.nome]) { src[chiavi[k]] = "cid:" + img.nome; passo(k + 1); return; }
      item.addFileAttachmentFromBase64Async(img.base64, img.nome, { isInline: true }, function (r) {
        if (r.status === Office.AsyncResultStatus.Succeeded) { src[chiavi[k]] = "cid:" + img.nome; }
        passo(k + 1);
      });
    };
    passo(0);
  });
}

function inserisciFirma(item, poi) {
  item.from.getAsync(function (res) {
    if (res.status !== Office.AsyncResultStatus.Succeeded || !res.value) {
      log("from.getAsync non riuscito: " + (res.error && res.error.message));
      poi(); return;
    }
    var indirizzo = (res.value.emailAddress || "").toLowerCase();
    log("mittente: " + indirizzo);
    preparaImmagini(item, function (src) {
      var html = costruisciFirma(indirizzo, res.value.displayName, src);
      item.body.setSignatureAsync(html, { coercionType: Office.CoercionType.Html }, function (r) {
        if (r.status !== Office.AsyncResultStatus.Succeeded) { log("setSignatureAsync errore: " + (r.error && r.error.message)); }
        poi();
      });
    });
  });
}

function onNewMessageComposeHandler(event) {
  inserisciFirma(Office.context.mailbox.item, function () { event.completed(); });
}

function onMessageFromChangedHandler(event) {
  inserisciFirma(Office.context.mailbox.item, function () { event.completed(); });
}

function onMessageRecipientsChangedHandler(event) {
  inserisciFirma(Office.context.mailbox.item, function () { event.completed(); });
}

function applicaFirmaPulsante(event) {
  inserisciFirma(Office.context.mailbox.item, function () { event.completed(); });
}

Office.onReady(function () {});
Office.actions.associate("onNewMessageComposeHandler", onNewMessageComposeHandler);
Office.actions.associate("onMessageFromChangedHandler", onMessageFromChangedHandler);
Office.actions.associate("onMessageRecipientsChangedHandler", onMessageRecipientsChangedHandler);
Office.actions.associate("applicaFirmaPulsante", applicaFirmaPulsante);
